VAR MetricaElegida = SELECTEDVALUE( Slicer_KPI[Metrica], "Rendimiento (%)" )
VAR Valor = [Metrica_Mapa_Seleccionada]
RETURN
SWITCH(
TRUE(),
// =========================
// RENDIMIENTO
// =========================
MetricaElegida = "RENDIMENT",
SWITCH(
TRUE(),
Valor < 0.70, "#D7191C",
Valor < 0.85, "#F46D43",
Valor < 0.95, "#FEE08B",
"#1A9641"
),
// =========================
// ANR
// =========================
MetricaElegida = "ANR",
SWITCH(
TRUE(),
Valor >= 100000, "#D7191C",
Valor >= 50000, "#F46D43",
Valor >= 25000, "#FEE08B",
"#1A9641"
),
// =========================
// CATEGORIZACIÃ“N ANR (solo RTH < 85%)
// =========================
MetricaElegida = "CATEGORIZACIO ANR",
SWITCH(
TRUE(),
[categoria_anr] = "Fugas", "#1F77B4",       // Azul
[categoria_anr] = "Fraude", "#D62728",      // Rojo
[categoria_anr] = "Subcontaje", "#F2C300",  // Amarillo
BLANK()
),
BLANK()
)
